[{"order":1,"type":"heading","text":"CRUD Operations in PHP: A Comprehensive Guide"},{"order":2,"type":"paragraph","text":"CRUD stands for Create, Read, Update, and Delete. These are the four basic operations performed on data in a database. This tutorial will guide you through implementing CRUD operations in PHP using MySQLi."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"A web server (e.g., Apache) with PHP installed."},{"order":5,"type":"bullet_point","text":"A MySQL database server."},{"order":6,"type":"bullet_point","text":"Basic knowledge of PHP and SQL."},{"order":7,"type":"subheading","text":"Database Setup"},{"order":8,"type":"paragraph","text":"First, create a database and a table. Let's create a database named 'crud_example' and a table named 'users'."},{"order":9,"type":"code","text":"CREATE DATABASE crud_example;
USE crud_example;

CREATE TABLE users (
 id INT AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(255) NOT NULL,
 email VARCHAR(255) NOT NULL
);"},{"order":10,"type":"subheading","text":"Configuration (config.php)"},{"order":11,"type":"paragraph","text":"Create a 'config.php' file to store your database credentials."},{"order":12,"type":"code","text":"<?php
$servername = "localhost";
$username = "your_username";
$password = "your_password";
$dbname = "crud_example";

// Create connection
$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
 die("Connection failed: " . $conn->connect_error);
}
?>"},{"order":13,"type":"subheading","text":"Create (create.php)"},{"order":14,"type":"paragraph","text":"This script handles the creation of new user records."},{"order":15,"type":"code","text":"<?php
include 'config.php';

if ($_SERVER["REQUEST_METHOD"] == "POST") {
 $name = $_POST['name'];
 $email = $_POST['email'];

 $sql = "INSERT INTO users (name, email) VALUES ('$name', '$email')";

 if ($conn->query($sql) === TRUE) {
 echo "New record created successfully";
 } else {
 echo "Error: " . $sql . "<br>" . $conn->error;
 }

 $conn->close();
}
?>

<form method="post">
 Name: <input type="text" name="name"><br><br>
 Email: <input type="email" name="email"><br><br>
 <input type="submit" value="Submit">
</form>"},{"order":16,"type":"subheading","text":"Read (read.php)"},{"order":17,"type":"paragraph","text":"This script retrieves and displays user records from the database."},{"order":18,"type":"code","text":"<?php
include 'config.php';

$sql = "SELECT id, name, email FROM users";
$result = $conn->query($sql);

if ($result->num_rows > 0) {
 // output data of each row
 while($row = $result->fetch_assoc()) {
 echo "id: " . $row["id"]. " - Name: " . $row["name"]. " - Email: " . $row["email"]. "<br>";
 }
} else {
 echo "0 results";
}
$conn->close();
?>"},{"order":19,"type":"subheading","text":"Update (update.php)"},{"order":20,"type":"paragraph","text":"This script allows you to update existing user records."},{"order":21,"type":"code","text":"<?php
include 'config.php';

if ($_SERVER["REQUEST_METHOD"] == "POST") {
 $id = $_POST['id'];
 $name = $_POST['name'];
 $email = $_POST['email'];

 $sql = "UPDATE users SET name='$name', email='$email' WHERE id=$id";

 if ($conn->query($sql) === TRUE) {
 echo "Record updated successfully";
 } else {
 echo "Error updating record: " . $conn->error;
 }

 $conn->close();
}
?>

<form method="post">
 ID: <input type="number" name="id"><br><br>
 Name: <input type="text" name="name"><br><br>
 Email: <input type="email" name="email"><br><br>
 <input type="submit" value="Update">
</form>"},{"order":22,"type":"subheading","text":"Delete (delete.php)"},{"order":23,"type":"paragraph","text":"This script deletes a user record from the database."},{"order":24,"type":"code","text":"<?php
include 'config.php';

if ($_SERVER["REQUEST_METHOD"] == "POST") {
 $id = $_POST['id'];

 $sql = "DELETE FROM users WHERE id=$id";

 if ($conn->query($sql) === TRUE) {
 echo "Record deleted successfully";
 } else {
 echo "Error deleting record: " . $conn->error;
 }

 $conn->close();
}
?>

<form method="post">
 ID: <input type="number" name="id"><br><br>
 <input type="submit" value="Delete">
</form>"},{"order":25,"type":"subheading","text":"Important Considerations"},{"order":26,"type":"bullet_point","text":"Always sanitize user inputs to prevent SQL injection. Use prepared statements or escape user input using 'mysqli_real_escape_string()'."},{"order":27,"type":"bullet_point","text":"Handle errors gracefully and provide informative messages to the user."},{"order":28,"type":"bullet_point","text":"Implement proper authentication and authorization to protect your data."},{"order":29,"type":"paragraph","text":"This tutorial provides a basic implementation of CRUD operations in PHP. You can expand upon this foundation to build more complex and secure applications."}]
